def equation(gate_voltage_abs: np.ndarray, drain_voltage_abs: np.ndarray, parameters: np.ndarray) -> np.ndarray:
    """Modelo empírico bivariado para log10(|ID|/A)."""
    """Improved version of the model, with higher-order terms and interaction terms."""
    a1, a2, a3, a4, b1, b2 = parameters
    return a1 + a2 * gate_voltage_abs + a3 * drain_voltage_abs + a4 * (gate_voltage_abs**2) + b1 * (gate_voltage_abs * drain_voltage_abs)
